if doc.is_stock_item == 1 and doc.is_sub_contracted_item == 1:
    bom_exists = frappe.db.get_value("BOM", {'item': doc.item_code})

    if not bom_exists:
        bom = frappe.new_doc("BOM")
        bom.item = doc.item_code
        bom.quantity = 1

        bom.append('items', {
            'item_code': doc.item_code,
            'qty': 1
        })

        bom.is_active = 1
        bom.insert()  # Insert also saves the document
        bom.submit()  # Submit the BOM to mark it as active
